(function(){const e=document.createElement("div");e.id="pageLoader",e.className="page-loader",e.innerHTML=`
        <div>
            <div class="loader-spinner"></div>
            <div class="loader-text">Please wait...</div>
        </div>
    `,document.addEventListener("DOMContentLoaded",()=>{document.body.appendChild(e)}),window.showLoader=function(d="Please wait..."){const t=document.getElementById("pageLoader");t&&(t.querySelector(".loader-text").textContent=d,t.classList.add("show"))},window.hideLoader=function(){const d=document.getElementById("pageLoader");d&&d.classList.remove("show")}})();
